import { ArrowLeft, ArrowUpRight, Check, ChevronRight, CircleHelp, Keyboard, MousePointer2, Radio, RotateCcw, Volume2, VolumeX, X, Zap } from "lucide-react";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import { SeoHead } from "../components/SeoHead";
import { SettingsControls } from "../components/SettingsControls";
import { usePreferences } from "../hooks/usePreferences";
import { links, nodes, palette, scenery, tracePolygon } from "./experience/experienceData";
import type { ExperienceNode, SceneBurst } from "./experience/experienceData";
import { createExperienceSound } from "./experience/experienceAudio";
import type { SoundEffect } from "./experience/experienceAudio";

type ControlMode = "pointer" | "keyboard";

export function ExperiencePage() {
  const { t } = useTranslation();
  const { resolvedTheme, motionEnabled } = usePreferences();
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const shellRef = useRef<HTMLDivElement>(null);
  const crosshairRef = useRef<HTMLDivElement>(null);
  const playerRef = useRef({ x: 0.5, y: 0.73, vx: 0, vy: 0 });
  const pointerRef = useRef({ x: 0.5, y: 0.5, active: false });
  const sceneBurstsRef = useRef<SceneBurst[]>([]);
  const hoveredRef = useRef("");
  const soundRef = useRef<ReturnType<typeof createExperienceSound> | null>(null);
  if (!soundRef.current) soundRef.current = createExperienceSound();
  const [started, setStarted] = useState(false);
  const [selectedId, setSelectedId] = useState("core");
  const [nearId, setNearId] = useState("core");
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [controlMode, setControlMode] = useState<ControlMode>("pointer");
  const selectedNode = useMemo(() => nodes.find((node) => node.id === selectedId) ?? nodes[0], [selectedId]);

  const playSound = useCallback((effect: SoundEffect) => {
    if (soundEnabled) soundRef.current?.play(effect);
  }, [soundEnabled]);

  // 音效开关切换时同步钢琴静音状态
  useEffect(() => {
    soundRef.current?.setPianoMuted(!soundEnabled);
  }, [soundEnabled]);

  useEffect(() => {
    const engine = soundRef.current;
    return () => engine?.dispose();
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const shell = shellRef.current;
    if (!canvas || !shell) return;
    const context = canvas.getContext("2d");
    if (!context) return;

    let frame = 0;
    let last = performance.now();
    let pulse = 0;
    let stepClock = 0;
    const keys = new Set<string>();
    const burstLifetime = 920;

    const resize = () => {
      const rect = shell.getBoundingClientRect();
      const ratio = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.max(1, Math.floor(rect.width * ratio));
      canvas.height = Math.max(1, Math.floor(rect.height * ratio));
      canvas.style.width = `${rect.width}px`;
      canvas.style.height = `${rect.height}px`;
      context.setTransform(ratio, 0, 0, ratio, 0, 0);
    };

    const movePlayer = (delta: number) => {
      const player = playerRef.current;
      const shift = controlMode === "keyboard" && (keys.has("ShiftLeft") || keys.has("ShiftRight"));
      const precision = controlMode === "keyboard" && (keys.has("ControlLeft") || keys.has("ControlRight"));
      const speed = started ? (precision ? 0.00011 : shift ? 0.00054 : 0.00028) : 0;
      let dx = 0;
      let dy = 0;
      if (keys.has("ArrowLeft") || keys.has("KeyA")) dx -= 1;
      if (keys.has("ArrowRight") || keys.has("KeyD")) dx += 1;
      if (keys.has("ArrowUp") || keys.has("KeyW")) dy -= 1;
      if (keys.has("ArrowDown") || keys.has("KeyS")) dy += 1;
      const keyboardActive = controlMode === "keyboard" && (dx !== 0 || dy !== 0);
      if (controlMode === "pointer" && pointerRef.current.active && started) {
        dx = pointerRef.current.x - player.x;
        dy = pointerRef.current.y - player.y;
        if (Math.hypot(dx, dy) < 0.025) { dx = 0; dy = 0; }
      }
      const distance = Math.hypot(dx, dy);
      if (distance > 0) { dx /= distance; dy /= distance; }
      const smoothing = 1 - Math.exp(-delta / (precision ? 28 : 52));
      player.vx += (dx * speed - player.vx) * smoothing;
      player.vy += (dy * speed - player.vy) * smoothing;
      if (!dx && !dy) { player.vx *= Math.pow(0.00005, delta / 1000); player.vy *= Math.pow(0.00005, delta / 1000); }
      player.x = Math.min(0.96, Math.max(0.04, player.x + player.vx));
      player.y = Math.min(0.93, Math.max(0.08, player.y + player.vy));
      if (keyboardActive && started) {
        stepClock += delta;
        if (stepClock > (precision ? 190 : shift ? 95 : 145)) { playSound("step"); stepClock = 0; }
      } else if (!keyboardActive) stepClock = 0;
    };

    const draw = (now: number) => {
      const delta = Math.min(48, Math.max(0, now - last));
      last = now;
      const rect = shell.getBoundingClientRect();
      const width = rect.width;
      const height = rect.height;
      const colors = palette[resolvedTheme === "light" ? "light" : "dark"];
      const nodePoint = (node: ExperienceNode) => ({ x: width * node.x, y: height * node.y });
      const nodeById = (id: string) => nodes.find((node) => node.id === id) ?? nodes[0];
      const pointDistance = (a: { x: number; y: number }, b: { x: number; y: number }) => Math.hypot(a.x - b.x, a.y - b.y);
      const player = playerRef.current;
      const playerPoint = { x: width * player.x, y: height * player.y };
      const pointerPoint = { x: width * pointerRef.current.x, y: height * pointerRef.current.y };
      const nearest = nodes.reduce((best, node) => {
        const distance = pointDistance(playerPoint, nodePoint(node));
        return distance < best.distance ? { id: node.id, distance } : best;
      }, { id: "core", distance: Number.POSITIVE_INFINITY });
      if (nearest.id !== nearId && nearest.distance < Math.min(width, height) * 0.14) setNearId(nearest.id);
      const pointerNearest = nodes.reduce((best, node) => {
        const distance = pointDistance(pointerPoint, nodePoint(node));
        return distance < best.distance ? { id: node.id, distance } : best;
      }, { id: "", distance: Number.POSITIVE_INFINITY });
      const hoveredId = pointerRef.current.active && pointerNearest.distance < Math.min(width, height) * 0.12 ? pointerNearest.id : "";
      if (hoveredId !== hoveredRef.current) {
        if (hoveredId) playSound("hover");
        hoveredRef.current = hoveredId;
      }

      context.clearRect(0, 0, width, height);
      context.fillStyle = colors.bg;
      context.fillRect(0, 0, width, height);
      const cameraX = pointerRef.current.active ? (pointerRef.current.x - 0.5) * 18 : Math.sin(now * 0.00045) * 3;
      const cameraY = pointerRef.current.active ? (pointerRef.current.y - 0.5) * 8 : Math.cos(now * 0.00038) * 2;
      const horizonY = height * 0.31 + cameraY;
      const environment = resolvedTheme === "light"
        ? { top: "#ffffff", middle: "#f5faff", floor: "#edf7fb", horizon: "rgba(0, 124, 158, 0.16)" }
        : { top: "#0d0b20", middle: "#1a1030", floor: "#070a12", horizon: "rgba(104, 216, 255, 0.2)" };
      const atmosphere = context.createLinearGradient(0, 0, 0, height);
      atmosphere.addColorStop(0, environment.top); atmosphere.addColorStop(0.46, environment.middle); atmosphere.addColorStop(1, environment.floor);
      context.fillStyle = atmosphere; context.fillRect(0, 0, width, height);
      const horizonGlow = context.createRadialGradient(width * 0.5 + cameraX, horizonY, 0, width * 0.5 + cameraX, horizonY, width * 0.68);
      horizonGlow.addColorStop(0, environment.horizon); horizonGlow.addColorStop(1, "transparent");
      context.fillStyle = horizonGlow; context.fillRect(0, 0, width, height);
      const gridSize = Math.max(34, Math.min(58, width / 24));
      const gridDrift = motionEnabled ? now * 0.018 : 0;
      const gridOffset = (gridDrift * 0.0008) % 1;
      const floorGradient = context.createLinearGradient(0, horizonY, 0, height);
      floorGradient.addColorStop(0, "transparent"); floorGradient.addColorStop(0.2, colors.grid); floorGradient.addColorStop(1, "transparent");
      context.fillStyle = floorGradient; context.fillRect(0, horizonY, width, height - horizonY);
      context.save(); context.translate(cameraX, 0); context.strokeStyle = colors.grid; context.lineWidth = 1;
      const gridCenter = width * 0.5;
      for (let ray = -18; ray <= 18; ray += 1) {
        const topX = gridCenter + ray * 22;
        const bottomX = gridCenter + ray * gridSize * 1.55;
        context.globalAlpha = ray % 3 === 0 ? 0.62 : 0.3;
        context.beginPath(); context.moveTo(topX, horizonY); context.lineTo(bottomX, height + 18); context.stroke();
      }
      for (let depth = -1; depth <= 13; depth += 1) {
        const progress = (depth + gridOffset) / 13;
        if (progress <= 0) continue;
        const perspective = Math.pow(Math.min(progress, 1.15), 1.72);
        const y = horizonY + perspective * (height - horizonY);
        context.globalAlpha = depth % 3 === 0 ? 0.55 : 0.24;
        context.beginPath(); context.moveTo(-width * 0.15, y); context.lineTo(width * 1.15, y); context.stroke();
      }
      context.restore();
      context.save(); context.globalAlpha = 0.8; context.strokeStyle = colors.cyan; context.lineWidth = 1.5;
      context.beginPath(); context.ellipse(width * 0.5 + cameraX, horizonY + 4, width * 0.26, 20, 0, Math.PI, Math.PI * 2); context.stroke();
      context.globalAlpha = 0.24; context.beginPath(); context.ellipse(width * 0.5 + cameraX, horizonY + 4, width * 0.42, 38, 0, Math.PI, Math.PI * 2); context.stroke(); context.restore();

      if (motionEnabled) {
        const scanY = ((now * 0.08) % (height + 140)) - 70;
        const scan = context.createLinearGradient(0, scanY - 28, 0, scanY + 28);
        scan.addColorStop(0, "transparent"); scan.addColorStop(0.5, colors.glow); scan.addColorStop(1, "transparent");
        context.fillStyle = scan; context.fillRect(0, scanY - 28, width, 56);
      }

      const gradient = context.createRadialGradient(playerPoint.x, playerPoint.y, 0, playerPoint.x, playerPoint.y, Math.min(width, height) * 0.45);
      gradient.addColorStop(0, colors.glow); gradient.addColorStop(1, "transparent");
      context.fillStyle = gradient; context.fillRect(0, 0, width, height);

      // ── 远景星尘（双层：近景亮点 + 远景微点），与 CSS FX 层呼应 ──
      context.save();
      context.globalAlpha = 0.55;
      for (let index = 0; index < 56; index += 1) {
        const driftX = (index * 173 + (motionEnabled ? now * (0.008 + (index % 3) * 0.002) : 0)) % (width + 40) - 20;
        const driftY = (index * 97 + (index % 5) * 31) % Math.max(height, 1);
        const near = index < 34;
        const radius = near ? (index % 4 === 0 ? 1.6 : 0.9) : (index % 5 === 0 ? 0.7 : 0.45);
        context.beginPath(); context.arc(driftX, driftY, radius, 0, Math.PI * 2);
        context.fillStyle = index % 3 === 0 ? colors.cyan : index % 3 === 1 ? colors.violet : colors.amber;
        context.globalAlpha = near ? 0.55 : 0.28;
        if (near) { context.shadowBlur = 6; context.shadowColor = context.fillStyle; } else { context.shadowBlur = 0; }
        context.fill();
      }
      context.shadowBlur = 0;
      context.restore();

      // ── 地平线二次辉光：在 canvas 内叠加一道柔和的青色光带，强化纵深 ──
      context.save();
      const horizonBand = context.createRadialGradient(width * 0.5 + cameraX, horizonY, 0, width * 0.5 + cameraX, horizonY, width * 0.52);
      horizonBand.addColorStop(0, resolvedTheme === "light" ? "rgba(0, 124, 158, 0.12)" : "rgba(104, 216, 255, 0.18)");
      horizonBand.addColorStop(0.55, resolvedTheme === "light" ? "rgba(90, 80, 200, 0.05)" : "rgba(155, 140, 255, 0.08)");
      horizonBand.addColorStop(1, "transparent");
      context.fillStyle = horizonBand;
      context.globalCompositeOperation = "screen";
      context.fillRect(0, horizonY - height * 0.18, width, height * 0.36);
      context.globalCompositeOperation = "source-over";
      context.restore();

      for (const landmark of scenery) {
        const landmarkX = width * landmark.x + cameraX * 0.65;
        const landmarkY = height * landmark.y + cameraY * 0.45;
        const landmarkColor = colors[landmark.color];
        const size = 17 * landmark.size;
        context.save();
        context.globalAlpha = 0.2;
        context.fillStyle = landmarkColor;
        context.beginPath(); context.ellipse(landmarkX, landmarkY + size * 0.9, size * 1.45, size * 0.42, 0, 0, Math.PI * 2); context.fill();
        context.globalAlpha = 0.72;
        context.strokeStyle = landmarkColor; context.shadowBlur = 18; context.shadowColor = landmarkColor;
        tracePolygon(context, landmarkX, landmarkY, size, 6, Math.PI / 6); context.stroke();
        context.globalAlpha = 0.38;
        tracePolygon(context, landmarkX, landmarkY - size * 0.45, size * 0.58, 6, Math.PI / 6); context.stroke();
        context.beginPath(); context.moveTo(landmarkX - size * 0.58, landmarkY - size * 0.45); context.lineTo(landmarkX - size * 0.58, landmarkY + size * 0.45); context.lineTo(landmarkX, landmarkY + size * 0.9); context.lineTo(landmarkX, landmarkY); context.stroke();
        context.beginPath(); context.moveTo(landmarkX + size * 0.58, landmarkY - size * 0.45); context.lineTo(landmarkX + size * 0.58, landmarkY + size * 0.45); context.lineTo(landmarkX, landmarkY + size * 0.9); context.stroke();
        context.globalAlpha = 0.22;
        context.beginPath(); context.moveTo(landmarkX, landmarkY - size * 0.6); context.lineTo(landmarkX, horizonY); context.stroke();
        context.restore();
      }

      for (const [fromId, toId] of links) {
        const from = nodePoint(nodeById(fromId)); const to = nodePoint(nodeById(toId));
        context.beginPath(); context.moveTo(from.x, from.y); context.lineTo(to.x, to.y);
        context.strokeStyle = colors.line; context.globalAlpha = 0.5; context.stroke(); context.globalAlpha = 1;
        if (motionEnabled) {
          const travel = ((now / 2400 + from.x / width + to.y / height) % 1);
          const px = from.x + (to.x - from.x) * travel; const py = from.y + (to.y - from.y) * travel;
          context.beginPath(); context.arc(px, py, 2.5, 0, Math.PI * 2); context.fillStyle = colors.cyan; context.shadowBlur = 14; context.shadowColor = colors.cyan; context.fill(); context.shadowBlur = 0;
        }
      }

      for (const node of nodes) {
        const point = nodePoint(node); const active = node.id === selectedId || node.id === nearId || node.id === hoveredId;
        const nodeColor = colors[node.color];
        const radius = node.radius + (active ? Math.sin(pulse + node.x * 8) * 2.5 : 0);

        // ── 节点外层柔光环：bloom 感的径向渐变，active 时更强 ──
        context.save();
        const haloRadius = radius * (active ? 3.6 : 2.4);
        const halo = context.createRadialGradient(point.x, point.y, radius * 0.4, point.x, point.y, haloRadius);
        halo.addColorStop(0, nodeColor);
        halo.addColorStop(0.45, nodeColor);
        halo.addColorStop(1, "transparent");
        context.globalAlpha = active ? 0.22 : 0.09;
        context.globalCompositeOperation = "screen";
        context.fillStyle = halo;
        context.beginPath(); context.arc(point.x, point.y, haloRadius, 0, Math.PI * 2); context.fill();
        context.globalCompositeOperation = "source-over";
        context.restore();

        context.save();
        context.globalAlpha = active ? 0.24 : 0.1;
        context.fillStyle = nodeColor;
        context.beginPath(); context.ellipse(point.x, point.y + radius * 0.92, radius * 1.35, radius * 0.3, 0, 0, Math.PI * 2); context.fill();
        context.globalAlpha = active ? 0.52 : 0.22;
        context.strokeStyle = nodeColor; context.lineWidth = 1;
        tracePolygon(context, point.x, point.y + 8, radius + 5, 6, Math.PI / 6); context.stroke();
        context.globalAlpha = active ? 0.32 : 0.14;
        tracePolygon(context, point.x, point.y - 3, radius * 0.78, 6, Math.PI / 6); context.stroke();
        context.restore();
        context.beginPath(); context.arc(point.x, point.y, radius + 12, 0, Math.PI * 2); context.strokeStyle = nodeColor; context.globalAlpha = active ? 0.26 : 0.11; context.lineWidth = 1; context.stroke(); context.globalAlpha = 1;
        context.beginPath(); context.arc(point.x, point.y, radius, 0, Math.PI * 2); context.fillStyle = colors.bg; context.fill(); context.strokeStyle = nodeColor; context.lineWidth = active ? 2.5 : 1.4; context.shadowBlur = active ? 24 : 9; context.shadowColor = nodeColor; context.stroke(); context.shadowBlur = 0;
        context.beginPath(); context.arc(point.x, point.y, 5, 0, Math.PI * 2); context.fillStyle = nodeColor; context.fill();
        if (active) {
          context.save(); context.translate(point.x, point.y); context.rotate(pulse * 0.18 + node.x);
          context.beginPath(); context.arc(0, 0, radius + 18, -0.38, 0.1); context.strokeStyle = nodeColor; context.globalAlpha = 0.85; context.lineWidth = 1.5; context.stroke();
          context.beginPath(); context.arc(0, 0, radius + 18, Math.PI - 0.1, Math.PI + 0.38); context.stroke(); context.restore();
        }
        if (width >= 600 || active) {
          context.fillStyle = colors.text; context.font = `${width < 600 ? 9 : 11}px Cascadia Code, monospace`;
          const labelOnLeft = node.x > 0.72;
          context.textAlign = labelOnLeft ? "right" : "left";
          context.fillText(t(node.labelKey).toUpperCase(), labelOnLeft ? point.x - radius - 10 : point.x + radius + 10, point.y + 4);
          context.textAlign = "left";
        }
      }

      sceneBurstsRef.current = sceneBurstsRef.current.filter((burst) => now - burst.created < burstLifetime);
      for (const burst of sceneBurstsRef.current) {
        const progress = Math.min(1, (now - burst.created) / burstLifetime);
        const burstPoint = { x: width * burst.x, y: height * burst.y };
        const burstColor = colors[burst.color];
        context.save(); context.globalAlpha = (1 - progress) * 0.9; context.strokeStyle = burstColor; context.shadowBlur = 18; context.shadowColor = burstColor;
        context.lineWidth = 2;
        context.beginPath(); context.arc(burstPoint.x, burstPoint.y, 12 + progress * 104, 0, Math.PI * 2); context.stroke();
        context.globalAlpha = (1 - progress) * 0.42;
        context.beginPath(); context.arc(burstPoint.x, burstPoint.y, 5 + progress * 54, 0, Math.PI * 2); context.stroke();
        for (let ray = 0; ray < 8; ray += 1) {
          const angle = (Math.PI * 2 * ray) / 8 + progress * 0.5;
          const inner = 18 + progress * 64; const outer = inner + 8;
          context.beginPath(); context.moveTo(burstPoint.x + Math.cos(angle) * inner, burstPoint.y + Math.sin(angle) * inner); context.lineTo(burstPoint.x + Math.cos(angle) * outer, burstPoint.y + Math.sin(angle) * outer); context.stroke();
        }
        context.restore();
      }

      context.save();
      for (let trail = 5; trail > 0; trail -= 1) {
        const trailAlpha = (6 - trail) / 34;
        context.globalAlpha = trailAlpha;
        context.beginPath(); context.arc(playerPoint.x - player.vx * trail * 900, playerPoint.y - player.vy * trail * 900, Math.max(2, 8 - trail), 0, Math.PI * 2); context.fillStyle = colors.cyan; context.fill();
      }
      context.restore();
      const angle = Math.atan2(player.vy, player.vx) || -Math.PI / 2;
      context.save(); context.translate(playerPoint.x, playerPoint.y); context.rotate(angle);
      context.beginPath(); context.moveTo(16, 0); context.lineTo(-10, -9); context.lineTo(-5, 0); context.lineTo(-10, 9); context.closePath(); context.fillStyle = colors.cyan; context.shadowBlur = 20; context.shadowColor = colors.cyan; context.fill(); context.shadowBlur = 0;
      context.beginPath(); context.arc(-5, 0, 4, 0, Math.PI * 2); context.fillStyle = colors.text; context.fill(); context.restore();

      pulse += motionEnabled ? delta * 0.004 : 0;
      movePlayer(delta);
      frame = motionEnabled || started ? requestAnimationFrame(draw) : 0;
    };

    const handleResize = () => { resize(); if (!frame) draw(performance.now()); };
    const handleKeyDown = (event: KeyboardEvent) => {
      if (["ArrowUp", "ArrowDown", "ArrowLeft", "ArrowRight", "KeyW", "KeyA", "KeyS", "KeyD", "ShiftLeft", "ShiftRight", "ControlLeft", "ControlRight"].includes(event.code)) { event.preventDefault(); keys.add(event.code); }
      if (event.key === "Escape") setSelectedId("");
    };
    const handleKeyUp = (event: KeyboardEvent) => { keys.delete(event.code); };
    const handlePointerMove = (event: PointerEvent) => {
      const bounds = canvas.getBoundingClientRect();
      const x = Math.min(1, Math.max(0, (event.clientX - bounds.left) / bounds.width));
      const y = Math.min(1, Math.max(0, (event.clientY - bounds.top) / bounds.height));
      pointerRef.current = { x, y, active: true };
      if (crosshairRef.current) { crosshairRef.current.style.left = `${x * 100}%`; crosshairRef.current.style.top = `${y * 100}%`; crosshairRef.current.style.opacity = "1"; }
    };
    const handlePointerDown = (event: PointerEvent) => { canvas.setPointerCapture?.(event.pointerId); handlePointerMove(event); };
    const handlePointerUp = (event: PointerEvent) => { if (canvas.hasPointerCapture?.(event.pointerId)) canvas.releasePointerCapture(event.pointerId); };
    const handlePointerLeave = () => { pointerRef.current.active = false; if (crosshairRef.current) crosshairRef.current.style.opacity = "0"; };
    const handleClick = (event: MouseEvent) => {
      if (!started) { setStarted(true); return; }
      const bounds = canvas.getBoundingClientRect();
      const click = { x: event.clientX - bounds.left, y: event.clientY - bounds.top };
      const hit = nodes.find((node) => Math.hypot(click.x - bounds.width * node.x, click.y - bounds.height * node.y) < node.radius + 20);
      sceneBurstsRef.current.push({ x: click.x / bounds.width, y: click.y / bounds.height, created: performance.now(), color: hit?.color ?? "cyan" });
      playSound("click");
      if (hit) setSelectedId(hit.id);
    };

    resize(); window.addEventListener("resize", handleResize); window.addEventListener("keydown", handleKeyDown); window.addEventListener("keyup", handleKeyUp); canvas.addEventListener("pointermove", handlePointerMove); canvas.addEventListener("pointerdown", handlePointerDown); canvas.addEventListener("pointerup", handlePointerUp); canvas.addEventListener("pointerleave", handlePointerLeave); canvas.addEventListener("click", handleClick);
    draw(performance.now());
    return () => { if (frame) cancelAnimationFrame(frame); window.removeEventListener("resize", handleResize); window.removeEventListener("keydown", handleKeyDown); window.removeEventListener("keyup", handleKeyUp); canvas.removeEventListener("pointermove", handlePointerMove); canvas.removeEventListener("pointerdown", handlePointerDown); canvas.removeEventListener("pointerup", handlePointerUp); canvas.removeEventListener("pointerleave", handlePointerLeave); canvas.removeEventListener("click", handleClick); };
  }, [controlMode, motionEnabled, nearId, playSound, resolvedTheme, selectedId, started, t]);

  const reset = () => { playerRef.current = { x: 0.5, y: 0.73, vx: 0, vy: 0 }; sceneBurstsRef.current = []; if (crosshairRef.current) crosshairRef.current.style.opacity = "0"; setSelectedId("core"); setNearId("core"); setStarted(false); soundRef.current?.stopPianoMusic(); };

  return (
    <>
      <SeoHead titleKey="seo.experienceTitle" descriptionKey="seo.experienceDescription" path="experience" />
      <main className="experience-page">
        <div className="experience-scene" ref={shellRef}>
        <canvas ref={canvasRef} tabIndex={0} aria-label={t("experience.sceneLabel")} />
        {/* 渲染特效层：bloom / 扫描线 / 光束 / 星尘 / 地平线辉光（纯装饰，不接收事件） */}
        <div className="experience-fx" aria-hidden="true">
          <div className="experience-fx__bloom" />
          <div className="experience-fx__horizon" />
          <div className="experience-fx__stars" />
          <div className="experience-fx__beam experience-fx__beam--a" />
          <div className="experience-fx__beam experience-fx__beam--b" />
          <div className="experience-fx__scanlines" />
        </div>
        <div className="experience-crosshair" ref={crosshairRef} aria-hidden="true"><span /><i /><b /></div>
        <header className="experience-topbar">
          <Link className="experience-brand" to="/"><img src="./branding/hongyunx-mark.svg" alt="" /><span><strong>{t("brand.name")}</strong><small>INTERACTIVE FIELD / 01</small></span></Link>
          <div className="experience-topbar__actions"><span className="experience-live"><i />{t("experience.live")}</span><SettingsControls /><Link className="experience-exit" to="/"><ArrowLeft size={14} />{t("experience.exit")}</Link></div>
        </header>

        {!started ? (
          <button className="experience-start" type="button" onClick={() => { setStarted(true); playSound("start"); soundRef.current?.startPianoMusic(); }} aria-label={t("experience.start")}>
            <span className="experience-start__eyebrow"><Radio size={16} />{t("experience.startEyebrow")}</span>
            <strong>{t("experience.startTitle")}</strong>
            <span>{t("experience.startDescription")}</span>
            <b><Zap size={16} fill="currentColor" />{t("experience.startAction")}<ArrowUpRight size={16} /></b>
          </button>
        ) : null}

        <section className="experience-hud experience-hud--left">
          <span>{t("experience.hudMission")}</span><strong>{t("experience.hudTitle")}</strong><small>{t("experience.hudDescription")}</small>
          <div className="experience-progress"><i style={{ width: `${Math.round((new Set([nearId, selectedId]).size / 2) * 100)}%` }} /></div>
          <em>{t("experience.hudHint")}</em>
        </section>

        <section className="experience-hud experience-hud--right">
          <div><span>{t("experience.hudSignal")}</span><b>11 / 11</b></div>
          <div><span>{t("experience.hudSurfaces")}</span><b>CLI + GUI</b></div>
          <div><span>{t("experience.hudInput")}</span><b>{controlMode === "pointer" ? <MousePointer2 size={13} /> : <Keyboard size={13} />} {t(controlMode === "pointer" ? "experience.modePointer" : "experience.modeKeyboard")}</b></div>
          <div><span>{t("experience.hudAudio")}</span><b>{soundEnabled ? "ON" : "MUTED"}</b></div>
          <div><span>{t("experience.hudMusic")}</span><b>{started && soundEnabled ? "♪ ON" : "OFF"}</b></div>
        </section>

        <div className="experience-controls"><div className="experience-mode-switch" role="group" aria-label={t("experience.controlMode")}><button className={controlMode === "pointer" ? "active" : ""} type="button" onClick={() => { setControlMode("pointer"); playSound("click"); }} aria-pressed={controlMode === "pointer"} title={t("experience.modePointerHint")}><MousePointer2 size={14} /><span>{t("experience.modePointer")}</span></button><button className={controlMode === "keyboard" ? "active" : ""} type="button" onClick={() => { setControlMode("keyboard"); canvasRef.current?.focus(); playSound("click"); }} aria-pressed={controlMode === "keyboard"} title={t("experience.modeKeyboardHint")}><Keyboard size={14} /><span>{t("experience.modeKeyboard")}</span></button></div><span className="experience-controls__touch"><MousePointer2 size={14} />{t("experience.controlTouch")}</span><button className="experience-sound" type="button" onClick={() => setSoundEnabled((enabled) => !enabled)} title={t(soundEnabled ? "experience.soundOff" : "experience.soundOn")} aria-label={t(soundEnabled ? "experience.soundOff" : "experience.soundOn")} aria-pressed={soundEnabled}>{soundEnabled ? <Volume2 size={14} /> : <VolumeX size={14} />}</button><button type="button" onClick={reset} title={t("experience.reset")} aria-label={t("experience.reset")}><RotateCcw size={14} /></button><button type="button" onClick={() => setSelectedId("")} title={t("experience.closePanel")} aria-label={t("experience.closePanel")}><X size={14} /></button></div>

        {selectedId ? (
          <aside className="experience-inspector">
            <div className="experience-inspector__header"><div><span>{t(selectedNode.labelKey).toUpperCase()}</span><h2>{t(selectedNode.titleKey)}</h2></div><button type="button" onClick={() => setSelectedId("")} aria-label={t("experience.closePanel")}><X size={17} /></button></div>
            <p>{t(selectedNode.bodyKey)}</p>
            <ul>{selectedNode.items.map((item) => <li key={item}><Check size={13} />{t(item)}</li>)}</ul>
            <Link to={selectedNode.id === "cli" ? "/docs/commands" : selectedNode.id === "gui" ? "/docs/gui" : "/docs"}>{t("experience.openDocs")}<ChevronRight size={15} /></Link>
          </aside>
        ) : null}

        <div className="experience-help"><CircleHelp size={14} />{t("experience.help")}</div>
        </div>
      </main>
    </>
  );
}
