// 2D / 3D 体验馆共享的 Web Audio 合成音效。
// 与 ExperiencePage.tsx 中的实现保持一致：master gain 0.075，短促合成音，无任何外部资源。
// 同时提供纯合成的钢琴氛围音乐：分层振荡器模拟琴弦谐波 + 指数衰减包络，
// 通过 lookahead 调度器循环播放一段五声音阶琶音，无需任何外部音频文件。

export type SoundEffect = "start" | "click" | "hover" | "step";

/** 钢琴音符频率（Hz）。基于 A4=440 的十二平均律。 */
const NOTE: Record<string, number> = {
  C3: 130.81, D3: 146.83, E3: 164.81, G3: 196.00, A3: 220.00, B3: 246.94,
  C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, G4: 392.00, A4: 440.00, B4: 493.88,
  C5: 523.25, D5: 587.33, E5: 659.25, G5: 783.99, A5: 880.00,
};

/**
 * 一段氛围钢琴旋律：五声音阶 (C/E/G/A/B) 为主的舒缓琶音。
 * 每小节约 4 拍，BPM ≈ 66，整体空灵、不抢戏。
 * [noteName, durationInBeats, velocity(0-1)]
 */
const PIANO_MELODY: Array<[string, number, number]> = [
  // 第 1 乐句：上行分解和弦
  ["C3", 2, 0.7], ["E3", 1, 0.55], ["G3", 1, 0.6],
  ["A3", 1.5, 0.65], ["C4", 1.5, 0.7], ["E4", 1, 0.55],
  // 第 2 乐句：高位徘徊后回落
  ["G4", 2, 0.75], ["E4", 1, 0.5], ["D4", 1, 0.45],
  ["C4", 1.5, 0.65], ["A3", 1.5, 0.6], ["G3", 1, 0.5],
  // 第 3 乐句：色彩变化（加入 B、F）
  ["E3", 2, 0.6], ["B3", 1, 0.5], ["D4", 1, 0.55],
  ["F4", 1.5, 0.6], ["E4", 1.5, 0.65], ["C4", 1, 0.5],
  // 第 4 乐句：回归主音，留白呼吸
  ["A3", 2, 0.6], ["C4", 1, 0.55], ["E4", 1, 0.5],
  ["G4", 2, 0.7], ["E4", 1, 0.45], ["C4", 1, 0.4],
  // 尾声：低音锚点 + 长延音
  ["C3", 3, 0.65], ["G3", 1, 0.4],
  ["A3", 2, 0.55], ["E4", 2, 0.5],
];

const BEAT_SECONDS = 60 / 66; // BPM 66 → 每拍约 0.909s

export function createExperienceSound() {
  const audio: { context: AudioContext | null; master: GainNode | null } = { context: null, master: null };

  // ── 钢琴音乐状态 ──
  let pianoPlaying = false;
  let pianoTimer: number | null = null;
  let nextNoteTime = 0;
  let melodyIndex = 0;
  let pianoMasterGain: GainNode | null = null;

  /** 确保 AudioContext 已初始化（懒创建，复用同一个 context/master） */
  const ensureContext = () => {
    if (typeof window === "undefined" || !window.AudioContext) return false;
    if (!audio.context) {
      audio.context = new window.AudioContext();
      audio.master = audio.context.createGain();
      audio.master.gain.value = 0.075;
      audio.master.connect(audio.context.destination);
    }
    if (audio.context.state === "suspended") void audio.context.resume();
    return true;
  };

  /**
   * 弹奏一个钢琴音符。
   * 使用分层振荡器模拟钢琴音色：基频 sine + 2/3/4 次谐波（triangle/sine），
   * 各自带独立的指数衰减包络，高频谐波衰减更快以模拟琴弦阻尼。
   */
  const playPianoNote = (frequency: number, startTime: number, velocity: number) => {
    const context = audio.context;
    const master = audio.master;
    if (!context || !master || !pianoMasterGain) return;

    const noteGain = context.createGain();
    noteGain.connect(pianoMasterGain);

    // 钢琴式 ADSR：快起音 (~5ms) → 中衰减 (~200ms) → 持续 (~0.3) → 长释放 (~1.2s)
    const attack = 0.005;
    const decay = 0.22;
    const sustainLevel = 0.28;
    const release = 1.4;
    const totalDuration = attack + decay + release;
    const peakVolume = Math.min(velocity * 0.9, 0.95);

    noteGain.gain.setValueAtTime(0.0001, startTime);
    noteGain.gain.exponentialRampToValueAtTime(peakVolume, startTime + attack);
    noteGain.gain.exponentialRampToValueAtTime(peakVolume * sustainLevel, startTime + attack + decay);
    noteGain.gain.exponentialRampToValueAtTime(0.0001, startTime + totalDuration);

    // 谐波层：[频率倍数, 波形, 相对音量, 额外衰减速率]
    const harmonics: Array<[number, OscillatorType, number, number]> = [
      [1, "sine", 0.55, 0],           // 基频
      [2, "triangle", 0.22, 0.15],     // 二次谐波（八度）
      [3, "sine", 0.12, 0.3],          // 三次谐波（十二度）
      [4, "sine", 0.06, 0.5],          // 四次谐波（双八度）
      [5, "triangle", 0.03, 0.7],      // 五次谐波（增加亮度）
    ];

    for (const [ratio, type, volume, extraDecay] of harmonics) {
      const oscillator = context.createOscillator();
      const harmonicGain = context.createGain();
      oscillator.type = type;
      oscillator.frequency.setValueAtTime(frequency * ratio, startTime);

      // 高频谐波衰减更快，模拟真实钢琴的琴弦阻尼特性
      const hPeak = volume * peakVolume;
      const hSustain = hPeak * sustainLevel * Math.max(0.1, 1 - extraDecay);
      harmonicGain.gain.setValueAtTime(0.0001, startTime);
      harmonicGain.gain.exponentialRampToValueAtTime(hPeak, startTime + attack);
      harmonicGain.gain.exponentialRampToValueAtTime(hSustain, startTime + attack + decay * (1 + extraDecay * 0.5));
      harmonicGain.gain.exponentialRampToValueAtTime(0.0001, startTime + totalDuration * Math.max(0.4, 1 - extraDecay * 0.4));

      oscillator.connect(harmonicGain);
      harmonicGain.connect(noteGain);
      oscillator.start(startTime);
      oscillator.stop(startTime + totalDuration + 0.05);
    }
  };

  /**
   * Lookahead 调度器：提前 ~100ms 将音符排入 AudioContext 时间线，
   * 保证节奏稳定不受 JS 主线程抖动影响。
   */
  const schedulePianoNotes = () => {
    if (!pianoPlaying || !audio.context) return;
    const lookahead = 0.12; // 提前 120ms 调度
    while (nextNoteTime < audio.context.currentTime + lookahead) {
      const [noteName, beats, velocity] = PIANO_MELODY[melodyIndex % PIANO_MELODY.length];
      const frequency = NOTE[noteName];
      if (frequency) {
        playPianoNote(frequency, nextNoteTime, velocity);
      }
      nextNoteTime += beats * BEAT_SECONDS;
      melodyIndex += 1;
    }
    // 每 25ms 检查一次是否需要调度新音符
    pianoTimer = window.setTimeout(schedulePianoNotes, 25);
  };

  /** 启动钢琴氛围音乐。需要用户手势后才能调用（浏览器自动播放策略）。 */
  const startPianoMusic = () => {
    if (pianoPlaying) return;
    if (!ensureContext()) return;
    if (!audio.context || !audio.master) return;

    // 钢琴独立音量总线，便于单独控制而不影响 SFX
    pianoMasterGain = audio.context.createGain();
    pianoMasterGain.gain.value = 0.38; // 相对于 SFX master 的比例
    pianoMasterGain.connect(audio.master);

    pianoPlaying = true;
    melodyIndex = 0;
    nextNoteTime = audio.context.currentTime + 0.15; // 稍作延迟避免爆音
    schedulePianoNotes();
  };

  /** 停止钢琴音乐并清理定时器。 */
  const stopPianoMusic = () => {
    pianoPlaying = false;
    if (pianoTimer !== null) {
      clearTimeout(pianoTimer);
      pianoTimer = null;
    }
    if (pianoMasterGain) {
      try { pianoMasterGain.disconnect(); } catch { /* already disconnected */ }
      pianoMasterGain = null;
    }
  };

  /** 暂停/恢复钢琴（配合 soundEnabled 切换）。 */
  const setPianoMuted = (muted: boolean) => {
    if (pianoMasterGain && audio.context) {
      const now = audio.context.currentTime;
      pianoMasterGain.gain.cancelScheduledValues(now);
      pianoMasterGain.gain.setValueAtTime(pianoMasterGain.gain.value, now);
      pianoMasterGain.gain.linearRampToValueAtTime(muted ? 0 : 0.38, now + 0.08);
    }
  };

  const play = (effect: SoundEffect) => {
    if (!ensureContext()) return;
    const context = audio.context;
    const master = audio.master;
    if (!context || !master) return;
    const now = context.currentTime;
    const tone = (frequency: number, duration: number, offset: number, volume: number, type: OscillatorType = "sine", glide = 0) => {
      const oscillator = context.createOscillator();
      const gain = context.createGain();
      oscillator.type = type;
      oscillator.frequency.setValueAtTime(frequency, now + offset);
      if (glide) oscillator.frequency.linearRampToValueAtTime(frequency + glide, now + offset + duration);
      gain.gain.setValueAtTime(0.0001, now + offset);
      gain.gain.exponentialRampToValueAtTime(volume, now + offset + 0.008);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + offset + duration);
      oscillator.connect(gain); gain.connect(master);
      oscillator.start(now + offset); oscillator.stop(now + offset + duration + 0.02);
    };
    if (effect === "start") {
      tone(196, 0.18, 0, 0.45, "sine", 38); tone(294, 0.2, 0.07, 0.32, "triangle", 54); tone(588, 0.34, 0.15, 0.22, "sine", 80);
    } else if (effect === "click") {
      tone(240, 0.11, 0, 0.34, "square", 120); tone(720, 0.16, 0.025, 0.16, "sine", -90);
    } else if (effect === "hover") {
      tone(620, 0.08, 0, 0.18, "sine", 45);
    } else {
      tone(110, 0.055, 0, 0.13, "triangle", -18);
    }
  };

  const dispose = () => {
    stopPianoMusic();
    if (audio.context) { void audio.context.close(); audio.context = null; audio.master = null; }
  };

  return { play, dispose, startPianoMusic, stopPianoMusic, setPianoMuted };
}
